def execute_script_report(self, filters):
	# save the timestamp to automatically set to prepared
	threshold = 15

	start_time = datetime.datetime.now()
	prepared_report_watcher = None
	if not self.prepared_report and not self.disable_prepared_report_automation:
		prepared_report_watcher = threading.Timer(
			interval=threshold,
			function=enable_prepared_report,
			kwargs={"report": self.name, "site": frappe.local.site},
		)
		prepared_report_watcher.start()

	# The JOB
	try:
		if self.is_standard == "Yes":
			if self.snapshot_report:
				res = self.execute_snapshot_report(filters)
			else:
				res = self.execute_module(filters)
		else:
			res = self.execute_script(filters)
	finally:
		prepared_report_watcher and prepared_report_watcher.cancel()

	execution_time = (datetime.datetime.now() - start_time).total_seconds()

	frappe.cache.hset("report_execution_time", self.name, execution_time)

	return res

get_column_as_dict_source:
def get_column_as_dict(col):
	col_dict = frappe._dict()

	# string
	if isinstance(col, str):
		col = col.split(":")
		if len(col) > 1:
			if "/" in col[1]:
				col_dict["fieldtype"], col_dict["options"] = col[1].split("/")
			else:
				col_dict["fieldtype"] = col[1]
			if len(col) == 3:
				col_dict["width"] = col[2]

		col_dict["label"] = col[0]
		col_dict["fieldname"] = frappe.scrub(col[0])

	# dict
	else:
		col_dict.update(col)
		if "fieldname" not in col_dict:
			col_dict["fieldname"] = frappe.scrub(col_dict["label"])

	return col_dict

translate_report_data_source:
def translate_report_data(data, total_row: bool):
	for d in data[:-1] if total_row else data:
		for field, value in d.items():
			if isinstance(value, str):
				d[field] = _(value)
	return data
